import { SECRET_COLUMNS, seal } from "../store/secrets.ts";
import type { Row } from "../store/rows.ts";

export function render(pattern: string, row: Row): string {
  const sealed = seal(pattern, row);
  const leaked = SECRET_COLUMNS[pattern];
  return JSON.stringify({ sealed, leaked });
}

