import { render } from "./render.ts";

export const app = {
  get(path: string, handler: (row: Record<string, unknown>) => string): readonly [string, (row: Record<string, unknown>) => string] {
    return [path, handler] as const;
  },
};

export function rows(row: Record<string, unknown>): string {
  return render("tokens", row);
}

app.get("/rows", rows);

